function i(r){if(!r)return"—";const t=Date.parse(r);if(Number.isNaN(t))return"—";const n=Math.round((Date.now()-t)/1e3);if(n<0||n<45)return"just now";if(n<90)return"1m ago";const e=Math.round(n/60);if(e<60)return`${e}m ago`;const o=Math.round(e/60);if(o<24)return`${o}h ago`;const u=Math.round(o/24);if(u<30)return`${u}d ago`;const a=Math.round(u/30);return a<12?`${a}mo ago`:`${Math.round(a/12)}y ago`}function s(r){if(!r)return"";const t=new Date(r);return Number.isNaN(t.getTime())?"":t.toISOString().replace("T"," ").replace(/\.\d+Z$/," UTC")}export{s as a,i as r};
